'use strict';

const fs = require('fs');
const path = require('path');

/**
 * Compute ON-vs-OFF token-usage ratios from JSONL transcript files.
 *
 * For each transcript, sums token fields across every line that carries a
 * `usage` object.  Lines whose `source === "mcp_tool"` are subtracted from
 * gross to produce the *net* metric (removes MCP plumbing overhead).
 *
 * @param {string} onTranscript  - path to the orchestrator-ON transcript JSONL
 * @param {string} offTranscript - path to the orchestrator-OFF transcript JSONL
 * @returns {{ gross: number|null, net: number|null, output: number|null }}
 */
function computeRatio(onTranscript, offTranscript) {
  const on = parseTranscript(onTranscript);
  const off = parseTranscript(offTranscript);

  const grossRatio = safeDivide(on.gross, off.gross);
  const netRatio   = safeDivide(on.net,   off.net);
  const outputRatio= safeDivide(on.output, off.output);

  return { gross: grossRatio, net: netRatio, output: outputRatio };
}

/**
 * Parse a single JSONL transcript file and return { gross, net, output }.
 *
 * - **gross**: sum of every token field on every line with `usage`.
 * - **net**  : gross minus the same sum restricted to `source === "mcp_tool"` lines.
 * - **output**: sum of `output_tokens` only (all lines with `usage`).
 */
function parseTranscript(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const lines = raw.split('\n');

  let gross = 0;
  let mcpTokens = 0;   // tokens on MCP tool-response lines (subtracted from gross → net)
  let output = 0;

  for (const line of lines) {
    if (!line.trim()) continue;

    let obj;
    try {
      obj = JSON.parse(line);
    } catch {
      // Not valid JSON — skip silently.
      continue;
    }

    const usage = obj.usage;
    if (!usage || typeof usage !== 'object') continue;

    const inputTokens     = usage.input_tokens     | 0;
    const outputTokens    = usage.output_tokens     | 0;
    const cacheRead       = usage.cache_read_input_tokens | 0;
    const cacheCreation   = usage.cache_creation_input_tokens | 0;

    const lineTotal = inputTokens + outputTokens + cacheRead + cacheCreation;

    gross += lineTotal;
    output += outputTokens;

    if (obj.source === 'mcp_tool') {
      mcpTokens += lineTotal;
    }
  }

  return { gross, net: gross - mcpTokens, output };
}

/**
 * Return numerator / denominator rounded to 4 decimal places, or `null` if
 * denominator is zero.
 */
function safeDivide(numerator, denominator) {
  if (denominator === 0) return null;
  return Math.round((numerator / denominator) * 10000) / 10000;
}

module.exports = { computeRatio };

