input.command:
node -e "
const { computeRatio } = require('./bench/sandbox/compute-ratio-ht.js');
const fs = require('fs');

// Example 1 — simple, no MCP plumbing
fs.writeFileSync('/tmp/on1.jsonl', JSON.stringify({role:'assistant',usage:{input_tokens:100,output_tokens:50,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n' + JSON.stringify({role:'assistant',usage:{input_tokens:80,output_tokens:30,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n');
fs.writeFileSync('/tmp/off1.jsonl', JSON.stringify({role:'assistant',usage:{input_tokens:200,output_tokens:100,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n');
console.log('Example 1:', JSON.stringify(computeRatio('/tmp/on1.jsonl', '/tmp/off1.jsonl')));
// Expected: { gross: 0.8667, net: 0.8667, output: 0.8 }

// Example 2 — with MCP plumbing
fs.writeFileSync('/tmp/on2.jsonl', JSON.stringify({role:'assistant',usage:{input_tokens:50,output_tokens:40,cache_read_input_tokens:2000,cache_creation_input_tokens:0}}) + '\n' + JSON.stringify({role:'assistant',source:'mcp_tool',usage:{input_tokens:10,output_tokens:5,cache_read_input_tokens:1800,cache_creation_input_tokens:0}}) + '\n');
fs.writeFileSync('/tmp/off2.jsonl', JSON.stringify({role:'assistant',usage:{input_tokens:200,output_tokens:80,cache_read_input_tokens:200,cache_creation_input_tokens:0}}) + '\n');
console.log('Example 2:', JSON.stringify(computeRatio('/tmp/on2.jsonl', '/tmp/off2.jsonl')));
// Expected: { gross: 8.1354, net: 4.3542, output: 0.5625 }

// Edge: zero denominator
fs.writeFileSync('/tmp/off_zero.jsonl', '');
console.log('Zero denom:', JSON.stringify(computeRatio('/tmp/on1.jsonl', '/tmp/off_zero.jsonl')));
// Expected: { gross: null, net: null, output: null }

// Edge: missing fields
fs.writeFileSync('/tmp/on_partial.jsonl', JSON.stringify({role:'assistant',usage:{output_tokens:50}}) + '\n');
fs.writeFileSync('/tmp/off_partial.jsonl', JSON.stringify({role:'assistant',usage:{input_tokens:100,output_tokens:30}}) + '\n');
console.log('Partial fields:', JSON.stringify(computeRatio('/tmp/on_partial.jsonl', '/tmp/off_partial.jsonl')));
// ON gross=50, OFF gross=130 → gross=0.3846; ON output=50, OFF output=30 → output=1.6667

// Edge: invalid JSON lines
fs.writeFileSync('/tmp/on_garbage.jsonl', 'not json\n' + JSON.stringify({role:'assistant',usage:{input_tokens:100,output_tokens:50,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n' + '{broken\n');
fs.writeFileSync('/tmp/off_garbage.jsonl', JSON.stringify({role:'assistant',usage:{input_tokens:200,output_tokens:100,cache_read_input_tokens:0,cache_creation_input_tokens:0}}) + '\n');
console.log('Garbage lines:', JSON.stringify(computeRatio('/tmp/on_garbage.jsonl', '/tmp/off_garbage.jsonl')));
// Expected: { gross: 0.5, net: 0.5, output: 0.5 }
"

